      const OpenAI = require("openai");
      const fs = require("fs")
      const client = new OpenAI({
          apiKey: "$MOONSHOT_API_KEY",
          baseURL: "https://api.moonshot.cn/v1",
      });
      async function main() {
          // xlnet.pdf 是一个示例文件, 我们支持 pdf, doc 以及图片等格式
          let file_object = await client.files.create({
